}
function drawStars(){
  for(const s of stars){
    const a=0.4+0.6*Math.abs(Math.sin(frame*0.05+s.tw));
    ctx.globalAlpha=a;
    ctx.fillStyle=s.c;
    ctx.fillRect(s.x|0,s.y|0,1,1);
  }
  ctx.globalAlpha=1;
}
function drawSprite(img,x,y){ctx.drawImage(img,x-8|0,y-8|0);}
function drawPlayerShip(x,y){ctx.drawImage(SPRITES.player,x-8,y-8);}
function drawHUD(){
