    const prev=stage<=7?denoms[Math.min(stage-2,5)]:[10,20,30,50][(stage-8)%4];
    const pcol={1:'#ffffff',5:'#0000ff',10:'#ffff00',20:'#ff0000',30:'#00ff00',50:'#ffffff'}[prev];
    ctx.fillStyle=pcol;
    ctx.fillRect(bx-18,272,16,10);
    ctx.fillStyle='#000000';
    ctx.fillText(''+prev,bx-16,280);
