}
function drawBeamCone(boss){
  const hw=4+Math.min(boss.beamT*0.12,20);
  ctx.fillStyle='rgba(0,100,255,0.4)';
  ctx.beginPath();
  ctx.moveTo(boss.x-3,boss.y);
  ctx.lineTo(boss.x-hw,H);
  ctx.lineTo(boss.x+hw,H);
  ctx.closePath();ctx.fill();
  ctx.fillStyle='rgba(100,180,255,0.6)';
  for(let i=0;i<3;i++){
    const y=boss.y+((frame*2+i*40)%(H-boss.y));
    const w=4+(y-boss.y)/(H-boss.y)*20;
    ctx.fillRect(boss.x-w|0,y|0,(w*2)|0,1);
  }
}
function drawExplosion(ex){
  const f=ex.frame;
  const n=3+Math.floor(f/3)+(ex.big?2:0);
  ctx.fillStyle=ex.color;
  for(let a=0;a<16;a++){
    const ang=a/16*6.283;
    const r=n+(a%2?2:0);
    ctx.fillRect(ex.x+Math.cos(ang)*r-1|0,ex.y+Math.sin(ang)*r-1|0,2,2);
  }
  if(f<6){ctx.fillStyle='#ffffff';ctx.fillRect(ex.x-2,ex.y-2,5,5);}
}
function render(){
  ctx.fillStyle='#000000';ctx.fillRect(0,0,W,H);
